using ModelContextProtocol;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithTools<WeatherTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets the current weather for a city")]
    public static string GetWeather(string city)
    {
        // Simulated weather data
        return $"Weather in {city}: 72°F, Partly Cloudy";
    }
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns application configuration data")]
    public static string GetAppSettings()
    {
        return """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "notifications": true
            }
        }
        """;
    }
}

