using ModelContextProtocol;
using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithTools<WeatherTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool]
    [System.ComponentModel.Description("Gets the current weather for a city")]
    public static string GetWeather(string city)
    {
        return $"Weather in {city}: 72°F, Partly Cloudy";
    }
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings")]
    public static string GetAppSettings()
    {
        return """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "notifications": true
            }
        }
        """;
    }
}

